def evolve(state: str, offsets: list[int], t: int) -> str:
    n = len(state)
    mask = (1 << n) - 1
    value = int(state[::-1], 2)

    shifts = set()
    for offset in offsets:
        shift = offset % n
        if shift in shifts:
            shifts.remove(shift)
        else:
            shifts.add(shift)

    while t:
        if t & 1:
            result = 0
            for shift in shifts:
                if shift:
                    result ^= (value >> shift) | ((value << (n - shift)) & mask)
                else:
                    result ^= value
            value = result

        t >>= 1
        if not t or not value:
            break

        next_shifts = set()
        for shift in shifts:
            shift = (2 * shift) % n
            if shift in next_shifts:
                next_shifts.remove(shift)
            else:
                next_shifts.add(shift)
        shifts = next_shifts

    return format(value, f"0{n}b")[::-1]
